 void SetupAdvancedCaptureH(){world.NewGame(0);world.WalletFunds=100000;world.Hangar["ore"]=2000;world.EnsureAdvancedH();advancedTabH=captureScene switch{"stage-h-regions"=>1,"stage-h-dens"=>2,"stage-h-campaigns"=>3,"stage-h-hulls"=>4,_=>0};if(advancedTabH==2){world.DeployDenH();world.FuelDenH(world.Advanced.Dens.Last().Id);world.AdvanceHours(2);}desktop.Clear();EnsureWindow(ViewMode.Advanced);}
 int checksUiH;void RunAdvancedUiChecksH(int frame){void Check(bool ok,string name){if(!ok)throw new Exception("STAGE H UI FAIL / "+name);checksUiH++;Console.WriteLine("STAGE H UI PASS / "+name);}void Click(string tip){var hit=ui.Hits.Last(h=>h.Tip==tip);TestClick(hit.Rect.Center.ToVector2());}
 if(frame==2){Click("Stage H issue / h_scout");Check(world.Advanced.Operations.Count==1,"Actual issue button creates tactical encounter");}
 if(frame==3){Click("Stage H tab / Campaigns");Check(advancedTabH==3,"Campaign tab");}
 if(frame==4){Click("Stage H campaign / Independent");Check(world.Advanced.Campaigns[0].Choice=="Independent","Voluntary independent choice");}
 if(frame==5){decimal before=world.Hangar["ore"];Click("Stage H campaign delivery");Check(world.Hangar["ore"]==before-100&&world.Advanced.Campaigns[0].Independent==10,"Delivery consumes real inventory");}
 if(frame==6){Click("Stage H tab / Mercenary dens");Check(advancedTabH==2,"Den tab");}
 if(frame==7){Click("Stage H den deploy");Check(world.Advanced.Dens.Count==1,"Costed owned den deployment");}
 if(frame==8){Click("Stage H den fuel");Check(world.Advanced.Dens[0].Fuel==100,"Fuel action consumes ore");}
 if(frame==9){Click("Stage H wait");Check(world.Advanced.Dens[0].State=="Online","Shared clock finishes anchoring");}
 if(frame==10){Click("Stage H tab / Special regions");Check(advancedTabH==1,"Regional travel tab");}
 if(frame==11){Click("Stage H transit kit");Check(world.Hangar.GetValueOrDefault("h_filament")==2,"Transit stock purchase");}
 if(frame==12){Click("Stage H tab / Modern hull audit");Check(advancedTabH==4,"Modern hull audit tab");}
 if(frame==13){Check(ui.Hits.Any(h=>h.Tip=="Stage H hull / Gaia"),"Source-only modern hull remains visible");Click("Stage H hull next");}
 if(frame==14){Check(advancedHullPageH==1&&ui.Hits.Any(h=>h.Tip=="Stage H hull / Pioneer"),"Second audit page reachable");Click("Stage H hull next");}
 if(frame==15){Check(advancedHullPageH==2&&ui.Hits.Any(h=>h.Tip=="Stage H hull / Cenotaph"),"Third audit page includes final hulls");Console.WriteLine(checksUiH+" Stage H UI checks passed.");}
 }
